 178→// writeTaskCheckpointEntries writes task-specific checkpoint entries and returns the task metadata path.
 179→func (s *GitStore) writeTaskCheckpointEntries(ctx context.Context, opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry) (string, error) {
 180→	taskPath := basePath + "tasks/" + opts.ToolUseID + "/"
 181→
 182→	if opts.IsIncremental {
 183→		return s.writeIncrementalTaskCheckpoint(opts, taskPath, entries)
 184→	}
 185→	return s.writeFinalTaskCheckpoint(ctx, opts, taskPath, entries)
 186→}
