 188→// writeIncrementalTaskCheckpoint writes an incremental checkpoint file during task execution.
 189→func (s *GitStore) writeIncrementalTaskCheckpoint(opts WriteCommittedOptions, taskPath string, entries map[string]object.TreeEntry) (string, error) {
 190→	incData, err := redact.JSONLBytes(opts.IncrementalData)
 191→	if err != nil {
 192→		return "", fmt.Errorf("failed to redact incremental checkpoint: %w", err)
 193→	}
 194→	checkpoint := incrementalCheckpointData{
 195→		Type:      opts.IncrementalType,
 196→		ToolUseID: opts.ToolUseID,
 197→		Timestamp: time.Now().UTC(),
 198→		Data:      incData,
 199→	}
 200→	cpData, err := jsonutil.MarshalIndentWithNewline(checkpoint, "", "  ")
 201→	if err != nil {
 202→		return "", fmt.Errorf("failed to marshal incremental checkpoint: %w", err)
 203→	}
 204→	cpBlobHash, err := CreateBlobFromContent(s.repo, cpData)
 205→	if err != nil {
 206→		return "", fmt.Errorf("failed to create incremental checkpoint blob: %w", err)
 207→	}
 208→
 209→	cpFilename := fmt.Sprintf("%03d-%s.json", opts.IncrementalSequence, opts.ToolUseID)
 210→	cpPath := taskPath + "checkpoints/" + cpFilename
 211→	entries[cpPath] = object.TreeEntry{
 212→		Name: cpPath,
 213→		Mode: filemode.Regular,
 214→		Hash: cpBlobHash,
 215→	}
 216→	return cpPath, nil
 217→}
