 219→// writeFinalTaskCheckpoint writes the final checkpoint.json and subagent transcript.
 220→func (s *GitStore) writeFinalTaskCheckpoint(ctx context.Context, opts WriteCommittedOptions, taskPath string, entries map[string]object.TreeEntry) (string, error) {
 221→	checkpoint := taskCheckpointData{
 222→		SessionID:      opts.SessionID,
 223→		ToolUseID:      opts.ToolUseID,
 224→		CheckpointUUID: opts.CheckpointUUID,
 225→		AgentID:        opts.AgentID,
 226→	}
 227→	checkpointData, err := jsonutil.MarshalIndentWithNewline(checkpoint, "", "  ")
 228→	if err != nil {
 229→		return "", fmt.Errorf("failed to marshal task checkpoint: %w", err)
 230→	}
 231→	blobHash, err := CreateBlobFromContent(s.repo, checkpointData)
 232→	if err != nil {
 233→		return "", fmt.Errorf("failed to create task checkpoint blob: %w", err)
 234→	}
 235→
 236→	checkpointFile := taskPath + "checkpoint.json"
 237→	entries[checkpointFile] = object.TreeEntry{
 238→		Name: checkpointFile,
 239→		Mode: filemode.Regular,
 240→		Hash: blobHash,
 241→	}
 242→
 243→	// Write subagent transcript if available
 244→	if opts.SubagentTranscriptPath != "" && opts.AgentID != "" {
 245→		agentContent, readErr := os.ReadFile(opts.SubagentTranscriptPath)
 246→		if readErr == nil {
 247→			// Try JSONL-aware redaction first; fall back to plain string redaction
 248→			// if the content is not valid JSONL (avoids silently dropping the transcript).
 249→			redacted, jsonlErr := redact.JSONLBytes(agentContent)
 250→			if jsonlErr != nil {
 251→				logging.Warn(ctx, "subagent transcript is not valid JSONL, falling back to plain redaction",
 252→					slog.String("path", opts.SubagentTranscriptPath),
 253→					slog.String("error", jsonlErr.Error()),
 254→				)
 255→				redacted = redact.Bytes(agentContent)
 256→			}
 257→			agentContent = redacted
 258→
 259→			agentBlobHash, agentBlobErr := CreateBlobFromContent(s.repo, agentContent)
 260→			if agentBlobErr == nil {
 261→				agentPath := taskPath + "agent-" + opts.AgentID + ".jsonl"
 262→				entries[agentPath] = object.TreeEntry{
 263→					Name: agentPath,
 264→					Mode: filemode.Regular,
 265→					Hash: agentBlobHash,
 266→				}
 267→			}
 268→		}
 269→	}
 270→
 271→	// Return task path without trailing slash
 272→	return taskPath[:len(taskPath)-1], nil
 273→}
 274→
 275→// writeStandardCheckpointEntries writes session files to numbered subdirectories and
 276→// maintains a CheckpointSummary at the root level with aggregated statistics.
 277→//
 278→// Structure:
 279→//
 280→//	basePath/
 281→//	├── metadata.json         # CheckpointSummary (aggregated stats)
 282→//	├── 1/                    # First session
 283→//	│   ├── metadata.json     # CommittedMetadata (session-specific, includes initial_attribution)
 284→//	│   ├── full.jsonl
 285→//	│   ├── prompt.txt
 286→//	│   └── content_hash.txt
 287→//	├── 2/                    # Second session
 288→//	└── ...
 289→func (s *GitStore) writeStandardCheckpointEntries(ctx context.Context, opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry) error {
 290→	// Read existing summary to get current session count
 291→	var existingSummary *CheckpointSummary
 292→	metadataPath := basePath + paths.MetadataFileName
 293→	if entry, exists := entries[metadataPath]; exists {
 294→		existing, err := s.readSummaryFromBlob(entry.Hash)
 295→		if err == nil {
 296→			existingSummary = existing
 297→		}
 298→	}
 299→
 300→	// Determine session index: reuse existing slot if session ID matches, otherwise append
 301→	sessionIndex := s.findSessionIndex(ctx, basePath, existingSummary, entries, opts.SessionID)
 302→
 303→	// Write session files to numbered subdirectory
 304→	sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
 305→	sessionFilePaths, err := s.writeSessionToSubdirectory(ctx, opts, sessionPath, entries)
 306→	if err != nil {
 307→		return err
 308→	}
 309→
 310→	// Copy additional metadata files from directory if specified (to session subdirectory)
 311→	if opts.MetadataDir != "" {
 312→		if err := s.copyMetadataDir(opts.MetadataDir, sessionPath, entries); err != nil {
 313→			return fmt.Errorf("failed to copy metadata directory: %w", err)
 314→		}
 315→	}
 316→
 317→	// Build the sessions array
 318→	var sessions []SessionFilePaths
 319→	if existingSummary != nil {
 320→		sessions = make([]SessionFilePaths, max(len(existingSummary.Sessions), sessionIndex+1))
 321→		copy(sessions, existingSummary.Sessions)
 322→	} else {
 323→		sessions = make([]SessionFilePaths, 1)
 324→	}
 325→	sessions[sessionIndex] = sessionFilePaths
 326→
 327→	// Update root metadata.json with CheckpointSummary
 328→	return s.writeCheckpointSummary(opts, basePath, entries, sessions)
 329→}
 330→
 331→// writeSessionToSubdirectory writes a single session's files to a numbered subdirectory.
 332→// Returns the absolute file paths from the git tree root for the sessions map.
 333→func (s *GitStore) writeSessionToSubdirectory(ctx context.Context, opts WriteCommittedOptions, sessionPath string, entries map[string]object.TreeEntry) (SessionFilePaths, error) {
 334→	filePaths := SessionFilePaths{}
 335→
 336→	// Clear any existing entries at this path so stale files from a previous
 337→	// write (e.g. prompt.txt) don't persist on overwrite.
 338→	for key := range entries {
 339→		if strings.HasPrefix(key, sessionPath) {
 340→			delete(entries, key)
 341→		}
 342→	}
 343→
 344→	// Write transcript
 345→	if err := s.writeTranscript(ctx, opts, sessionPath, entries); err != nil {
 346→		return filePaths, err
 347→	}
 348→	filePaths.Transcript = "/" + sessionPath + paths.TranscriptFileName
 349→	filePaths.ContentHash = "/" + sessionPath + paths.ContentHashFileName
 350→
 351→	// Write prompts
 352→	if len(opts.Prompts) > 0 {
 353→		promptContent := redact.String(strings.Join(opts.Prompts, "\n\n---\n\n"))
 354→		blobHash, err := CreateBlobFromContent(s.repo, []byte(promptContent))
 355→		if err != nil {
 356→			return filePaths, err
 357→		}
 358→		entries[sessionPath+paths.PromptFileName] = object.TreeEntry{
 359→			Name: sessionPath + paths.PromptFileName,
 360→			Mode: filemode.Regular,
 361→			Hash: blobHash,
 362→		}
 363→		filePaths.Prompt = "/" + sessionPath + paths.PromptFileName
 364→	}
 365→
 366→	// Write session-level metadata.json (CommittedMetadata with all fields including initial_attribution)
 367→	sessionMetadata := CommittedMetadata{
 368→		CheckpointID:                opts.CheckpointID,
 369→		SessionID:                   opts.SessionID,
 370→		Strategy:                    opts.Strategy,
 371→		CreatedAt:                   time.Now().UTC(),
 372→		Branch:                      opts.Branch,
 373→		CheckpointsCount:            opts.CheckpointsCount,
 374→		FilesTouched:                opts.FilesTouched,
 375→		Agent:                       opts.Agent,
 376→		Model:                       opts.Model,
 377→		TurnID:                      opts.TurnID,
 378→		IsTask:                      opts.IsTask,
 379→		ToolUseID:                   opts.ToolUseID,
 380→		TranscriptIdentifierAtStart: opts.TranscriptIdentifierAtStart,
 381→		CheckpointTranscriptStart:   opts.CheckpointTranscriptStart,
 382→		TranscriptLinesAtStart:      opts.CheckpointTranscriptStart, // Deprecated: kept for backward compat
 383→		TokenUsage:                  opts.TokenUsage,
 384→		SessionMetrics:              opts.SessionMetrics,
 385→		InitialAttribution:          opts.InitialAttribution,
 386→		Summary:                     redactSummary(opts.Summary),
 387→		CLIVersion:                  versioninfo.Version,
 388→	}
 389→
 390→	metadataJSON, err := jsonutil.MarshalIndentWithNewline(sessionMetadata, "", "  ")
 391→	if err != nil {
 392→		return filePaths, fmt.Errorf("failed to marshal session metadata: %w", err)
 393→	}
 394→	metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
 395→	if err != nil {
 396→		return filePaths, err
 397→	}
 398→	entries[sessionPath+paths.MetadataFileName] = object.TreeEntry{
 399→		Name: sessionPath + paths.MetadataFileName,
 400→		Mode: filemode.Regular,
 401→		Hash: metadataHash,
 402→	}
 403→	filePaths.Metadata = "/" + sessionPath + paths.MetadataFileName
 404→
 405→	return filePaths, nil
 406→}
 407→
 408→// writeCheckpointSummary writes the root-level CheckpointSummary with aggregated statistics.
 409→// sessions is the complete sessions array (already built by the caller).
 410→func (s *GitStore) writeCheckpointSummary(opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry, sessions []SessionFilePaths) error {
 411→	checkpointsCount, filesTouched, tokenUsage, err :=
 412→		s.reaggregateFromEntries(basePath, len(sessions), entries)
 413→	if err != nil {
 414→		return fmt.Errorf("failed to aggregate session stats: %w", err)
 415→	}
 416→
 417→	summary := CheckpointSummary{
 418→		CheckpointID:     opts.CheckpointID,
 419→		CLIVersion:       versioninfo.Version,
 420→		Strategy:         opts.Strategy,
 421→		Branch:           opts.Branch,
 422→		CheckpointsCount: checkpointsCount,
 423→		FilesTouched:     filesTouched,
 424→		Sessions:         sessions,
 425→		TokenUsage:       tokenUsage,
 426→	}
 427→
 428→	metadataJSON, err := jsonutil.MarshalIndentWithNewline(summary, "", "  ")
 429→	if err != nil {
 430→		return fmt.Errorf("failed to marshal checkpoint summary: %w", err)
 431→	}
 432→	metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
 433→	if err != nil {
 434→		return err
 435→	}
 436→	entries[basePath+paths.MetadataFileName] = object.TreeEntry{
 437→		Name: basePath + paths.MetadataFileName,
 438→		Mode: filemode.Regular,
 439→		Hash: metadataHash,
 440→	}
 441→	return nil
 442→}
 443→
 444→// findSessionIndex returns the index of an existing session with the given ID,
 445→// or the next available index if not found. This prevents duplicate session entries.
 446→func (s *GitStore) findSessionIndex(ctx context.Context, basePath string, existingSummary *CheckpointSummary, entries map[string]object.TreeEntry, sessionID string) int {
 447→	if existingSummary == nil {
 448→		return 0
 449→	}
 450→	for i := range len(existingSummary.Sessions) {
 451→		path := fmt.Sprintf("%s%d/%s", basePath, i, paths.MetadataFileName)
 452→		if entry, exists := entries[path]; exists {
 453→			meta, err := s.readMetadataFromBlob(entry.Hash)
 454→			if err != nil {
 455→				logging.Warn(ctx, "failed to read session metadata during dedup check",
 456→					slog.Int("session_index", i),
 457→					slog.String("session_id", sessionID),
 458→					slog.String("error", err.Error()),
 459→				)
 460→				continue
 461→			}
 462→			if meta.SessionID == sessionID {
 463→				return i
 464→			}
 465→		}
 466→	}
 467→	return len(existingSummary.Sessions)
 468→}
 469→
 470→// reaggregateFromEntries reads all session metadata from the entries map and
 471→// reaggregates CheckpointsCount, FilesTouched, and TokenUsage.
 472→func (s *GitStore) reaggregateFromEntries(basePath string, sessionCount int, entries map[string]object.TreeEntry) (int, []string, *agent.TokenUsage, error) {
 473→	var totalCount int
 474→	var allFiles []string
 475→	var totalTokens *agent.TokenUsage
 476→
 477→	for i := range sessionCount {
 478→		path := fmt.Sprintf("%s%d/%s", basePath, i, paths.MetadataFileName)
 479→		entry, exists := entries[path]
 480→		if !exists {
 481→			return 0, nil, nil, fmt.Errorf("session %d metadata not found at %s", i, path)
 482→		}
 483→		meta, err := s.readMetadataFromBlob(entry.Hash)
 484→		if err != nil {
 485→			return 0, nil, nil, fmt.Errorf("failed to read session %d metadata: %w", i, err)
 486→		}
 487→		totalCount += meta.CheckpointsCount
 488→		allFiles = mergeFilesTouched(allFiles, meta.FilesTouched)
 489→		totalTokens = aggregateTokenUsage(totalTokens, meta.TokenUsage)
 490→	}
 491→
 492→	return totalCount, allFiles, totalTokens, nil
 493→}
 494→
 495→// readJSONFromBlob reads JSON from a blob hash and decodes it to the given type.
 496→func readJSONFromBlob[T any](repo *git.Repository, hash plumbing.Hash) (*T, error) {
 497→	blob, err := repo.BlobObject(hash)
 498→	if err != nil {
 499→		return nil, fmt.Errorf("failed to get blob: %w", err)
 500→	}
 501→
 502→	reader, err := blob.Reader()
 503→	if err != nil {
 504→		return nil, fmt.Errorf("failed to get blob reader: %w", err)
 505→	}
 506→	defer reader.Close()
 507→
 508→	var result T
 509→	if err := json.NewDecoder(reader).Decode(&result); err != nil {
 510→		return nil, fmt.Errorf("failed to decode: %w", err)
 511→	}
 512→
 513→	return &result, nil
 514→}
