 516→// readSummaryFromBlob reads CheckpointSummary from a blob hash.
 517→func (s *GitStore) readSummaryFromBlob(hash plumbing.Hash) (*CheckpointSummary, error) {
 518→	return readJSONFromBlob[CheckpointSummary](s.repo, hash)
 519→}
