 521→// aggregateTokenUsage sums two TokenUsage structs.
 522→// Returns nil if both inputs are nil.
 523→func aggregateTokenUsage(a, b *agent.TokenUsage) *agent.TokenUsage {
 524→	if a == nil && b == nil {
 525→		return nil
 526→	}
 527→	result := &agent.TokenUsage{}
 528→	if a != nil {
 529→		result.InputTokens = a.InputTokens
 530→		result.CacheCreationTokens = a.CacheCreationTokens
 531→		result.CacheReadTokens = a.CacheReadTokens
 532→		result.OutputTokens = a.OutputTokens
 533→		result.APICallCount = a.APICallCount
 534→	}
 535→	if b != nil {
 536→		result.InputTokens += b.InputTokens
 537→		result.CacheCreationTokens += b.CacheCreationTokens
 538→		result.CacheReadTokens += b.CacheReadTokens
 539→		result.OutputTokens += b.OutputTokens
 540→		result.APICallCount += b.APICallCount
 541→	}
 542→	return result
 543→}
