 545→// writeTranscript writes the transcript file from in-memory content or file path.
 546→// If the transcript exceeds MaxChunkSize, it's split into multiple chunk files.
 547→func (s *GitStore) writeTranscript(ctx context.Context, opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry) error {
 548→	transcript := opts.Transcript
 549→	if len(transcript) == 0 && opts.TranscriptPath != "" {
 550→		var readErr error
 551→		transcript, readErr = os.ReadFile(opts.TranscriptPath)
 552→		if readErr != nil {
 553→			// Non-fatal: transcript may not exist yet
 554→			transcript = nil
 555→		}
 556→	}
 557→	if len(transcript) == 0 {
 558→		return nil
 559→	}
 560→
 561→	// Redact secrets before chunking so content hash reflects redacted content
 562→	transcript, err := redact.JSONLBytes(transcript)
 563→	if err != nil {
 564→		return fmt.Errorf("failed to redact transcript secrets: %w", err)
 565→	}
 566→
 567→	// Chunk the transcript if it's too large
 568→	chunks, err := agent.ChunkTranscript(ctx, transcript, opts.Agent)
 569→	if err != nil {
 570→		return fmt.Errorf("failed to chunk transcript: %w", err)
 571→	}
 572→
 573→	// Write chunk files
 574→	for i, chunk := range chunks {
 575→		chunkPath := basePath + agent.ChunkFileName(paths.TranscriptFileName, i)
 576→		blobHash, err := CreateBlobFromContent(s.repo, chunk)
 577→		if err != nil {
 578→			return err
 579→		}
 580→		entries[chunkPath] = object.TreeEntry{
 581→			Name: chunkPath,
 582→			Mode: filemode.Regular,
 583→			Hash: blobHash,
 584→		}
 585→	}
 586→
 587→	// Content hash for deduplication (hash of full transcript)
 588→	contentHash := fmt.Sprintf("sha256:%x", sha256.Sum256(transcript))
 589→	hashBlob, err := CreateBlobFromContent(s.repo, []byte(contentHash))
 590→	if err != nil {
 591→		return err
 592→	}
 593→	entries[basePath+paths.ContentHashFileName] = object.TreeEntry{
 594→		Name: basePath + paths.ContentHashFileName,
 595→		Mode: filemode.Regular,
 596→		Hash: hashBlob,
 597→	}
 598→	return nil
 599→}
 600→
 601→// mergeFilesTouched combines two file lists, removing duplicates.
 602→func mergeFilesTouched(existing, additional []string) []string {
 603→	seen := make(map[string]bool)
 604→	var result []string
 605→
 606→	for _, f := range existing {
 607→		if !seen[f] {
 608→			seen[f] = true
 609→			result = append(result, f)
 610→		}
 611→	}
 612→	for _, f := range additional {
 613→		if !seen[f] {
 614→			seen[f] = true
 615→			result = append(result, f)
 616→		}
 617→	}
 618→
 619→	sort.Strings(result)
 620→	return result
 621→}
