 623→// redactSummary returns a copy of the summary with text fields redacted.
 624→// Structural fields (Path, Line, EndLine) are preserved.
 625→// NOTE: When adding new text fields to Summary, LearningsSummary, or CodeLearning,
 626→// update this function to include them in redaction.
 627→func redactSummary(s *Summary) *Summary {
 628→	if s == nil {
 629→		return nil
 630→	}
 631→	return &Summary{
 632→		Intent:    redact.String(s.Intent),
 633→		Outcome:   redact.String(s.Outcome),
 634→		Friction:  redactStringSlice(s.Friction),
 635→		OpenItems: redactStringSlice(s.OpenItems),
 636→		Learnings: LearningsSummary{
 637→			Repo:     redactStringSlice(s.Learnings.Repo),
 638→			Workflow: redactStringSlice(s.Learnings.Workflow),
 639→			Code:     redactCodeLearnings(s.Learnings.Code),
 640→		},
 641→	}
 642→}
 643→
 644→// redactStringSlice applies redact.String to each element.
 645→func redactStringSlice(ss []string) []string {
 646→	if ss == nil {
 647→		return nil
 648→	}
 649→	out := make([]string, len(ss))
 650→	for i, s := range ss {
 651→		out[i] = redact.String(s)
 652→	}
 653→	return out
 654→}
 655→
 656→// redactCodeLearnings redacts only the Finding field, preserving Path/Line/EndLine.
 657→func redactCodeLearnings(cls []CodeLearning) []CodeLearning {
 658→	if cls == nil {
 659→		return nil
 660→	}
 661→	out := make([]CodeLearning, len(cls))
 662→	for i, cl := range cls {
 663→		out[i] = CodeLearning{
 664→			Path:    cl.Path,
 665→			Line:    cl.Line,
 666→			EndLine: cl.EndLine,
 667→			Finding: redact.String(cl.Finding),
 668→		}
 669→	}
 670→	return out
 671→}
