 673→// readMetadataFromBlob reads CommittedMetadata from a blob hash.
 674→func (s *GitStore) readMetadataFromBlob(hash plumbing.Hash) (*CommittedMetadata, error) {
 675→	return readJSONFromBlob[CommittedMetadata](s.repo, hash)
 676→}
