 678→// buildCommitMessage constructs the commit message with proper trailers.
 679→// The commit subject is always "Checkpoint: <id>" for consistency.
 680→// If CommitSubject is provided (e.g., for task checkpoints), it's included in the body.
 681→func (s *GitStore) buildCommitMessage(opts WriteCommittedOptions, taskMetadataPath string) string {
 682→	var commitMsg strings.Builder
 683→
 684→	// Subject line is always the checkpoint ID for consistent formatting
 685→	fmt.Fprintf(&commitMsg, "Checkpoint: %s\n\n", opts.CheckpointID)
 686→
 687→	// Include custom description in body if provided (e.g., task checkpoint details)
 688→	if opts.CommitSubject != "" {
 689→		commitMsg.WriteString(opts.CommitSubject + "\n\n")
 690→	}
 691→	fmt.Fprintf(&commitMsg, "%s: %s\n", trailers.SessionTrailerKey, opts.SessionID)
 692→	fmt.Fprintf(&commitMsg, "%s: %s\n", trailers.StrategyTrailerKey, opts.Strategy)
 693→	if opts.Agent != "" {
 694→		fmt.Fprintf(&commitMsg, "%s: %s\n", trailers.AgentTrailerKey, opts.Agent)
 695→	}
 696→	if opts.EphemeralBranch != "" {
 697→		fmt.Fprintf(&commitMsg, "%s: %s\n", trailers.EphemeralBranchTrailerKey, opts.EphemeralBranch)
 698→	}
 699→	if taskMetadataPath != "" {
 700→		fmt.Fprintf(&commitMsg, "%s: %s\n", trailers.MetadataTaskTrailerKey, taskMetadataPath)
 701→	}
 702→
 703→	return commitMsg.String()
 704→}
