 723→
 724→// ReadCommitted reads a committed checkpoint's summary by ID from the entire/checkpoints/v1 branch.
 725→// Returns only the CheckpointSummary (paths + aggregated stats), not actual content.
 726→// Use ReadSessionContent to read actual transcript/prompts/context.
 727→// Returns nil, nil if the checkpoint doesn't exist.
 728→//
 729→// The storage format uses numbered subdirectories for each session (0-based):
 730→//
 731→//	<checkpoint-id>/
 732→//	├── metadata.json      # CheckpointSummary with sessions map
 733→//	├── 0/                 # First session
 734→//	│   ├── metadata.json  # Session-specific metadata
 735→//	│   └── full.jsonl     # Transcript
 736→//	├── 1/                 # Second session
 737→//	└── ...
 738→func (s *GitStore) ReadCommitted(ctx context.Context, checkpointID id.CheckpointID) (*CheckpointSummary, error) {
 739→	if err := ctx.Err(); err != nil {
 740→		return nil, err //nolint:wrapcheck // Propagating context cancellation
 741→	}
 742→
 743→	ft, err := s.getFetchingTree(ctx)
 744→	if err != nil {
 745→		return nil, nil //nolint:nilnil,nilerr // No sessions branch means no checkpoint exists
 746→	}
 747→
 748→	checkpointPath := checkpointID.Path()
 749→	checkpointTree, err := ft.Tree(checkpointPath)
 750→	if err != nil {
 751→		return nil, nil //nolint:nilnil,nilerr // Checkpoint directory not found
 752→	}
 753→
 754→	// Read root metadata.json as CheckpointSummary (auto-fetches blob if needed)
 755→	metadataFile, err := checkpointTree.File(paths.MetadataFileName)
 756→	if err != nil {
 757→		return nil, nil //nolint:nilnil,nilerr // metadata.json not found
 758→	}
 759→
 760→	content, err := metadataFile.Contents()
 761→	if err != nil {
 762→		return nil, fmt.Errorf("failed to read metadata.json: %w", err)
 763→	}
 764→
 765→	var summary CheckpointSummary
 766→	if err := json.Unmarshal([]byte(content), &summary); err != nil {
 767→		return nil, fmt.Errorf("failed to parse metadata.json: %w", err)
 768→	}
 769→
 770→	return &summary, nil
 771→}
 772→
 773→// ReadSessionContent reads the actual content for a specific session within a checkpoint.
 774→// sessionIndex is 0-based (0 for first session, 1 for second, etc.).
 775→// Returns the session's metadata, transcript, prompts, and context.
 776→// Returns an error if the checkpoint or session doesn't exist.
 777→func (s *GitStore) ReadSessionContent(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*SessionContent, error) {
 778→	if err := ctx.Err(); err != nil {
 779→		return nil, err //nolint:wrapcheck // Propagating context cancellation
 780→	}
 781→
 782→	ft, err := s.getFetchingTree(ctx)
 783→	if err != nil {
 784→		return nil, ErrCheckpointNotFound
 785→	}
 786→
 787→	checkpointPath := checkpointID.Path()
 788→	checkpointTree, err := ft.Tree(checkpointPath)
 789→	if err != nil {
 790→		return nil, ErrCheckpointNotFound
 791→	}
 792→
 793→	// Get the session subdirectory
 794→	sessionDir := strconv.Itoa(sessionIndex)
 795→	sessionTree, err := checkpointTree.Tree(sessionDir)
 796→	if err != nil {
 797→		return nil, fmt.Errorf("session %d not found: %w", sessionIndex, err)
 798→	}
 799→
 800→	result := &SessionContent{}
 801→
 802→	// Read session-specific metadata (auto-fetches blob if needed)
 803→	var agentType types.AgentType
 804→	if metadataFile, fileErr := sessionTree.File(paths.MetadataFileName); fileErr == nil {
 805→		if content, contentErr := metadataFile.Contents(); contentErr == nil {
 806→			if jsonErr := json.Unmarshal([]byte(content), &result.Metadata); jsonErr == nil {
 807→				agentType = result.Metadata.Agent
 808→			}
 809→		}
 810→	}
 811→
 812→	// Read transcript (auto-fetches blobs if needed)
 813→	if transcript, transcriptErr := readTranscriptFromTree(ctx, sessionTree, agentType); transcriptErr == nil && transcript != nil {
 814→		result.Transcript = transcript
 815→	}
 816→
 817→	// Read prompts (auto-fetches blob if needed)
 818→	if file, fileErr := sessionTree.File(paths.PromptFileName); fileErr == nil {
 819→		if content, contentErr := file.Contents(); contentErr == nil {
 820→			result.Prompts = content
 821→		}
 822→	}
 823→
 824→	return result, nil
 825→}
