 872→// ListCommitted lists all committed checkpoints from the entire/checkpoints/v1 branch.
 873→// Scans sharded paths: <id[:2]>/<id[2:]>/ directories containing metadata.json.
 874→//
 875→
 876→func (s *GitStore) ListCommitted(ctx context.Context) ([]CommittedInfo, error) {
 877→	if err := ctx.Err(); err != nil {
 878→		return nil, err //nolint:wrapcheck // Propagating context cancellation
 879→	}
 880→
 881→	tree, err := s.getSessionsBranchTree()
 882→	if err != nil {
 883→		return []CommittedInfo{}, nil //nolint:nilerr // No sessions branch means empty list
 884→	}
 885→
 886→	var checkpoints []CommittedInfo
 887→
 888→	// Scan sharded structure: <2-char-prefix>/<remaining-id>/metadata.json
 889→	for _, bucketEntry := range tree.Entries {
 890→		if bucketEntry.Mode != filemode.Dir {
 891→			continue
 892→		}
 893→		// Bucket should be 2 hex chars
 894→		if len(bucketEntry.Name) != 2 {
 895→			continue
 896→		}
 897→
 898→		bucketTree, treeErr := s.repo.TreeObject(bucketEntry.Hash)
 899→		if treeErr != nil {
 900→			continue
 901→		}
 902→
 903→		// Each entry in the bucket is the remaining part of the checkpoint ID
 904→		for _, checkpointEntry := range bucketTree.Entries {
 905→			if checkpointEntry.Mode != filemode.Dir {
 906→				continue
 907→			}
 908→
 909→			checkpointTree, cpTreeErr := s.repo.TreeObject(checkpointEntry.Hash)
 910→			if cpTreeErr != nil {
 911→				continue
 912→			}
 913→
 914→			// Reconstruct checkpoint ID: <bucket><remaining>
 915→			checkpointIDStr := bucketEntry.Name + checkpointEntry.Name
 916→			checkpointID, cpIDErr := id.NewCheckpointID(checkpointIDStr)
 917→			if cpIDErr != nil {
 918→				// Skip invalid checkpoint IDs (shouldn't happen with our own data)
 919→				continue
 920→			}
 921→
 922→			info := CommittedInfo{
 923→				CheckpointID: checkpointID,
 924→			}
 925→
 926→			// Get details from root metadata file (CheckpointSummary format)
 927→			if metadataFile, fileErr := checkpointTree.File(paths.MetadataFileName); fileErr == nil {
 928→				if content, contentErr := metadataFile.Contents(); contentErr == nil {
 929→					var summary CheckpointSummary
 930→					if err := json.Unmarshal([]byte(content), &summary); err == nil {
 931→						info.CheckpointsCount = summary.CheckpointsCount
 932→						info.FilesTouched = summary.FilesTouched
 933→						info.SessionCount = len(summary.Sessions)
 934→
 935→						// Read session metadata from latest session to get Agent, SessionID, CreatedAt
 936→						if len(summary.Sessions) > 0 {
 937→							latestIndex := len(summary.Sessions) - 1
 938→							latestDir := strconv.Itoa(latestIndex)
 939→							if sessionTree, treeErr := checkpointTree.Tree(latestDir); treeErr == nil {
 940→								if sessionMetadataFile, smErr := sessionTree.File(paths.MetadataFileName); smErr == nil {
 941→									if sessionContent, scErr := sessionMetadataFile.Contents(); scErr == nil {
 942→										var sessionMetadata CommittedMetadata
 943→										if json.Unmarshal([]byte(sessionContent), &sessionMetadata) == nil {
 944→											info.Agent = sessionMetadata.Agent
 945→											info.SessionID = sessionMetadata.SessionID
 946→											info.CreatedAt = sessionMetadata.CreatedAt
 947→										}
 948→									}
 949→								}
 950→							}
 951→						}
 952→					}
 953→				}
 954→			}
 955→
 956→			checkpoints = append(checkpoints, info)
 957→		}
 958→	}
 959→
 960→	// Sort by time (most recent first)
 961→	sort.Slice(checkpoints, func(i, j int) bool {
 962→		return checkpoints[i].CreatedAt.After(checkpoints[j].CreatedAt)
 963→	})
 964→
 965→	return checkpoints, nil
 966→}
