 968→// GetTranscript retrieves the transcript for a specific checkpoint ID.
 969→// Returns the latest session's transcript.
 970→func (s *GitStore) GetTranscript(ctx context.Context, checkpointID id.CheckpointID) ([]byte, error) {
 971→	content, err := s.ReadLatestSessionContent(ctx, checkpointID)
 972→	if err != nil {
 973→		return nil, err
 974→	}
 975→	if len(content.Transcript) == 0 {
 976→		return nil, fmt.Errorf("no transcript found for checkpoint: %s", checkpointID)
 977→	}
 978→	return content.Transcript, nil
 979→}
