 981→// GetSessionLog retrieves the session transcript and session ID for a checkpoint.
 982→// This is the primary method for looking up session logs by checkpoint ID.
 983→// Returns ErrCheckpointNotFound if the checkpoint doesn't exist.
 984→// Returns ErrNoTranscript if the checkpoint exists but has no transcript.
 985→func (s *GitStore) GetSessionLog(ctx context.Context, cpID id.CheckpointID) ([]byte, string, error) {
 986→	content, err := s.ReadLatestSessionContent(ctx, cpID)
 987→	if err != nil {
 988→		if errors.Is(err, ErrCheckpointNotFound) {
 989→			return nil, "", ErrCheckpointNotFound
 990→		}
 991→		return nil, "", fmt.Errorf("failed to read checkpoint: %w", err)
 992→	}
 993→	if len(content.Transcript) == 0 {
 994→		return nil, "", ErrNoTranscript
 995→	}
 996→	return content.Transcript, content.Metadata.SessionID, nil
 997→}
