1013→// UpdateSummary updates the summary field in the latest session's metadata.
1014→// Returns ErrCheckpointNotFound if the checkpoint doesn't exist.
1015→func (s *GitStore) UpdateSummary(ctx context.Context, checkpointID id.CheckpointID, summary *Summary) error {
1016→	if err := ctx.Err(); err != nil {
1017→		return err //nolint:wrapcheck // Propagating context cancellation
1018→	}
1019→
1020→	// Ensure sessions branch exists
1021→	if err := s.ensureSessionsBranch(); err != nil {
1022→		return fmt.Errorf("failed to ensure sessions branch: %w", err)
1023→	}
1024→
1025→	// Get branch ref and root tree hash (O(1), no flatten)
1026→	parentHash, rootTreeHash, err := s.getSessionsBranchRef()
1027→	if err != nil {
1028→		return err
1029→	}
1030→
1031→	// Flatten only the checkpoint subtree
1032→	basePath := checkpointID.Path() + "/"
1033→	checkpointPath := checkpointID.Path()
1034→	entries, err := s.flattenCheckpointEntries(rootTreeHash, checkpointPath)
1035→	if err != nil {
1036→		return err
1037→	}
1038→
1039→	// Read root CheckpointSummary to find the latest session
1040→	rootMetadataPath := basePath + paths.MetadataFileName
1041→	entry, exists := entries[rootMetadataPath]
1042→	if !exists {
1043→		return ErrCheckpointNotFound
1044→	}
1045→
1046→	checkpointSummary, err := s.readSummaryFromBlob(entry.Hash)
1047→	if err != nil {
1048→		return fmt.Errorf("failed to read checkpoint summary: %w", err)
1049→	}
1050→
1051→	// Find the latest session's metadata path (0-based indexing)
1052→	latestIndex := len(checkpointSummary.Sessions) - 1
1053→	sessionMetadataPath := fmt.Sprintf("%s%d/%s", basePath, latestIndex, paths.MetadataFileName)
1054→	sessionEntry, exists := entries[sessionMetadataPath]
1055→	if !exists {
1056→		return fmt.Errorf("session metadata not found at %s", sessionMetadataPath)
1057→	}
1058→
1059→	// Read and update session metadata
1060→	existingMetadata, err := s.readMetadataFromBlob(sessionEntry.Hash)
1061→	if err != nil {
1062→		return fmt.Errorf("failed to read session metadata: %w", err)
1063→	}
1064→
1065→	// Update the summary
1066→	existingMetadata.Summary = redactSummary(summary)
1067→
1068→	// Write updated session metadata
1069→	metadataJSON, err := jsonutil.MarshalIndentWithNewline(existingMetadata, "", "  ")
1070→	if err != nil {
1071→		return fmt.Errorf("failed to marshal metadata: %w", err)
1072→	}
1073→	metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
1074→	if err != nil {
1075→		return fmt.Errorf("failed to create metadata blob: %w", err)
1076→	}
1077→	entries[sessionMetadataPath] = object.TreeEntry{
1078→		Name: sessionMetadataPath,
1079→		Mode: filemode.Regular,
1080→		Hash: metadataHash,
1081→	}
1082→
1083→	// Build checkpoint subtree and splice into root (O(depth) tree surgery)
1084→	newTreeHash, err := s.spliceCheckpointSubtree(rootTreeHash, checkpointID, basePath, entries)
1085→	if err != nil {
1086→		return err
1087→	}
1088→
1089→	authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
1090→	commitMsg := fmt.Sprintf("Update summary for checkpoint %s (session: %s)", checkpointID, existingMetadata.SessionID)
1091→	newCommitHash, err := s.createCommit(newTreeHash, parentHash, commitMsg, authorName, authorEmail)
1092→	if err != nil {
1093→		return err
1094→	}
1095→
1096→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
1097→	newRef := plumbing.NewHashReference(refName, newCommitHash)
1098→	if err := s.repo.Storer.SetReference(newRef); err != nil {
1099→		return fmt.Errorf("failed to set branch reference: %w", err)
1100→	}
1101→
1102→	return nil
1103→}
1104→
1105→// UpdateCommitted replaces the transcript, prompts, and context for an existing
1106→// committed checkpoint. Uses replace semantics: the full session transcript is
1107→// written, replacing whatever was stored at initial condensation time.
1108→//
1109→// This is called at stop time to finalize all checkpoints from the current turn
1110→// with the complete session transcript (from prompt to stop event).
1111→//
1112→// Returns ErrCheckpointNotFound if the checkpoint doesn't exist.
1113→func (s *GitStore) UpdateCommitted(ctx context.Context, opts UpdateCommittedOptions) error {
1114→	if opts.CheckpointID.IsEmpty() {
1115→		return errors.New("invalid update options: checkpoint ID is required")
1116→	}
1117→
1118→	// Ensure sessions branch exists
1119→	if err := s.ensureSessionsBranch(); err != nil {
1120→		return fmt.Errorf("failed to ensure sessions branch: %w", err)
1121→	}
1122→
1123→	// Get branch ref and root tree hash (O(1), no flatten)
1124→	parentHash, rootTreeHash, err := s.getSessionsBranchRef()
1125→	if err != nil {
1126→		return err
1127→	}
1128→
1129→	// Flatten only the checkpoint subtree
1130→	basePath := opts.CheckpointID.Path() + "/"
1131→	checkpointPath := opts.CheckpointID.Path()
1132→	entries, err := s.flattenCheckpointEntries(rootTreeHash, checkpointPath)
1133→	if err != nil {
1134→		return err
1135→	}
1136→
1137→	// Read root CheckpointSummary to find the session slot
1138→	rootMetadataPath := basePath + paths.MetadataFileName
1139→	entry, exists := entries[rootMetadataPath]
1140→	if !exists {
1141→		return ErrCheckpointNotFound
1142→	}
1143→
1144→	checkpointSummary, err := s.readSummaryFromBlob(entry.Hash)
1145→	if err != nil {
1146→		return fmt.Errorf("failed to read checkpoint summary: %w", err)
1147→	}
1148→	if len(checkpointSummary.Sessions) == 0 {
1149→		return ErrCheckpointNotFound
1150→	}
1151→
1152→	// Find session index matching opts.SessionID
1153→	sessionIndex := -1
1154→	for i := range len(checkpointSummary.Sessions) {
1155→		metaPath := fmt.Sprintf("%s%d/%s", basePath, i, paths.MetadataFileName)
1156→		if metaEntry, metaExists := entries[metaPath]; metaExists {
1157→			meta, metaErr := s.readMetadataFromBlob(metaEntry.Hash)
1158→			if metaErr == nil && meta.SessionID == opts.SessionID {
1159→				sessionIndex = i
1160→				break
1161→			}
1162→		}
1163→	}
1164→	if sessionIndex == -1 {
1165→		// Fall back to latest session; log so mismatches are diagnosable.
1166→		sessionIndex = len(checkpointSummary.Sessions) - 1
1167→		logging.Debug(ctx, "UpdateCommitted: session ID not found, falling back to latest",
1168→			slog.String("session_id", opts.SessionID),
1169→			slog.String("checkpoint_id", string(opts.CheckpointID)),
1170→			slog.Int("fallback_index", sessionIndex),
1171→		)
1172→	}
1173→
1174→	sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
1175→
1176→	// Replace transcript (full replace, not append)
1177→	// Apply redaction as safety net (caller should redact, but we ensure it here)
1178→	if len(opts.Transcript) > 0 {
1179→		transcript, err := redact.JSONLBytes(opts.Transcript)
1180→		if err != nil {
1181→			return fmt.Errorf("failed to redact transcript secrets: %w", err)
1182→		}
1183→		if err := s.replaceTranscript(ctx, transcript, opts.Agent, sessionPath, entries); err != nil {
1184→			return fmt.Errorf("failed to replace transcript: %w", err)
1185→		}
1186→	}
1187→
1188→	// Replace prompts (apply redaction as safety net)
1189→	if len(opts.Prompts) > 0 {
1190→		promptContent := redact.String(strings.Join(opts.Prompts, "\n\n---\n\n"))
1191→		blobHash, err := CreateBlobFromContent(s.repo, []byte(promptContent))
1192→		if err != nil {
1193→			return fmt.Errorf("failed to create prompt blob: %w", err)
1194→		}
1195→		entries[sessionPath+paths.PromptFileName] = object.TreeEntry{
1196→			Name: sessionPath + paths.PromptFileName,
1197→			Mode: filemode.Regular,
1198→			Hash: blobHash,
1199→		}
1200→	}
1201→
1202→	// Build checkpoint subtree and splice into root (O(depth) tree surgery)
1203→	newTreeHash, err := s.spliceCheckpointSubtree(rootTreeHash, opts.CheckpointID, basePath, entries)
1204→	if err != nil {
1205→		return err
1206→	}
1207→
1208→	authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
1209→	commitMsg := fmt.Sprintf("Finalize transcript for Checkpoint: %s", opts.CheckpointID)
1210→	newCommitHash, err := s.createCommit(newTreeHash, parentHash, commitMsg, authorName, authorEmail)
1211→	if err != nil {
1212→		return err
1213→	}
1214→
1215→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
1216→	newRef := plumbing.NewHashReference(refName, newCommitHash)
1217→	if err := s.repo.Storer.SetReference(newRef); err != nil {
1218→		return fmt.Errorf("failed to set branch reference: %w", err)
1219→	}
1220→
1221→	return nil
1222→}
