1224→// replaceTranscript writes the full transcript content, replacing any existing transcript.
1225→// Also removes any chunk files from a previous write and updates the content hash.
1226→func (s *GitStore) replaceTranscript(ctx context.Context, transcript []byte, agentType types.AgentType, sessionPath string, entries map[string]object.TreeEntry) error {
1227→	// Remove existing transcript files (base + any chunks)
1228→	transcriptBase := sessionPath + paths.TranscriptFileName
1229→	for key := range entries {
1230→		if key == transcriptBase || strings.HasPrefix(key, transcriptBase+".") {
1231→			delete(entries, key)
1232→		}
1233→	}
1234→
1235→	// Chunk the transcript (matches writeTranscript behavior)
1236→	chunks, err := agent.ChunkTranscript(ctx, transcript, agentType)
1237→	if err != nil {
1238→		return fmt.Errorf("failed to chunk transcript: %w", err)
1239→	}
1240→
1241→	// Write chunk files
1242→	for i, chunk := range chunks {
1243→		chunkPath := sessionPath + agent.ChunkFileName(paths.TranscriptFileName, i)
1244→		blobHash, err := CreateBlobFromContent(s.repo, chunk)
1245→		if err != nil {
1246→			return fmt.Errorf("failed to create transcript blob: %w", err)
1247→		}
1248→		entries[chunkPath] = object.TreeEntry{
1249→			Name: chunkPath,
1250→			Mode: filemode.Regular,
1251→			Hash: blobHash,
1252→		}
1253→	}
1254→
1255→	// Update content hash
1256→	contentHash := fmt.Sprintf("sha256:%x", sha256.Sum256(transcript))
1257→	hashBlob, err := CreateBlobFromContent(s.repo, []byte(contentHash))
1258→	if err != nil {
1259→		return fmt.Errorf("failed to create content hash blob: %w", err)
1260→	}
1261→	hashPath := sessionPath + paths.ContentHashFileName
1262→	entries[hashPath] = object.TreeEntry{
1263→		Name: hashPath,
1264→		Mode: filemode.Regular,
1265→		Hash: hashBlob,
1266→	}
1267→
1268→	return nil
1269→}
