1271→// ensureSessionsBranch ensures the entire/checkpoints/v1 branch exists.
1272→func (s *GitStore) ensureSessionsBranch() error {
1273→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
1274→	_, err := s.repo.Reference(refName, true)
1275→	if err == nil {
1276→		return nil // Branch exists
1277→	}
1278→
1279→	// Create orphan branch with empty tree
1280→	emptyTreeHash, err := BuildTreeFromEntries(s.repo, make(map[string]object.TreeEntry))
1281→	if err != nil {
1282→		return err
1283→	}
1284→
1285→	authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
1286→	commitHash, err := s.createCommit(emptyTreeHash, plumbing.ZeroHash, "Initialize sessions branch", authorName, authorEmail)
1287→	if err != nil {
1288→		return err
1289→	}
1290→
1291→	newRef := plumbing.NewHashReference(refName, commitHash)
1292→	if err := s.repo.Storer.SetReference(newRef); err != nil {
1293→		return fmt.Errorf("failed to set branch reference: %w", err)
1294→	}
1295→	return nil
1296→}
