1309→// getSessionsBranchTree returns the tree object for the entire/checkpoints/v1 branch.
1310→// Falls back to origin/entire/checkpoints/v1 if the local branch doesn't exist.
1311→func (s *GitStore) getSessionsBranchTree() (*object.Tree, error) {
1312→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
1313→	ref, err := s.repo.Reference(refName, true)
1314→	if err != nil {
1315→		// Local branch doesn't exist, try remote-tracking branch
1316→		remoteRefName := plumbing.NewRemoteReferenceName("origin", paths.MetadataBranchName)
1317→		ref, err = s.repo.Reference(remoteRefName, true)
1318→		if err != nil {
1319→			return nil, fmt.Errorf("sessions branch not found: %w", err)
1320→		}
1321→	}
1322→
1323→	commit, err := s.repo.CommitObject(ref.Hash())
1324→	if err != nil {
1325→		return nil, fmt.Errorf("failed to get commit object: %w", err)
1326→	}
1327→
1328→	tree, err := commit.Tree()
1329→	if err != nil {
1330→		return nil, fmt.Errorf("failed to get commit tree: %w", err)
1331→	}
1332→
1333→	return tree, nil
1334→}
