1336→// CreateBlobFromContent creates a blob object from in-memory content.
1337→// Exported for use by strategy package (session_test.go)
1338→func CreateBlobFromContent(repo *git.Repository, content []byte) (plumbing.Hash, error) {
1339→	obj := repo.Storer.NewEncodedObject()
1340→	obj.SetType(plumbing.BlobObject)
1341→	obj.SetSize(int64(len(content)))
1342→
1343→	writer, err := obj.Writer()
1344→	if err != nil {
1345→		return plumbing.ZeroHash, fmt.Errorf("failed to get object writer: %w", err)
1346→	}
1347→
1348→	_, err = writer.Write(content)
1349→	if err != nil {
1350→		_ = writer.Close()
1351→		return plumbing.ZeroHash, fmt.Errorf("failed to write blob content: %w", err)
1352→	}
1353→	if err := writer.Close(); err != nil {
1354→		return plumbing.ZeroHash, fmt.Errorf("failed to close blob writer: %w", err)
1355→	}
1356→
1357→	hash, err := repo.Storer.SetEncodedObject(obj)
1358→	if err != nil {
1359→		return plumbing.ZeroHash, fmt.Errorf("failed to store blob object: %w", err)
1360→	}
1361→	return hash, nil
1362→}
1363→
1364→// copyMetadataDir copies all files from a directory to the checkpoint path.
1365→// Used to include additional metadata files like task checkpoints, subagent transcripts, etc.
1366→func (s *GitStore) copyMetadataDir(metadataDir, basePath string, entries map[string]object.TreeEntry) error {
1367→	err := filepath.Walk(metadataDir, func(path string, info os.FileInfo, err error) error {
1368→		if err != nil {
1369→			return err
1370→		}
1371→
1372→		// Skip symlinks to prevent reading files outside the metadata directory.
1373→		// A symlink could point to sensitive files (e.g., /etc/passwd) which would
1374→		// then be captured in the checkpoint and stored in git history.
1375→		// NOTE: filepath.Walk uses os.Stat (follows symlinks), so info.Mode() never
1376→		// reports ModeSymlink. We use os.Lstat to check the entry itself.
1377→		// This check MUST come before IsDir() because Walk follows symlinked
1378→		// directories and would recurse into them otherwise.
1379→		linfo, lstatErr := os.Lstat(path)
1380→		if lstatErr != nil {
1381→			return fmt.Errorf("failed to lstat %s: %w", path, lstatErr)
1382→		}
1383→		if linfo.Mode()&os.ModeSymlink != 0 {
1384→			if info.IsDir() {
1385→				return filepath.SkipDir
1386→			}
1387→			return nil
1388→		}
1389→
1390→		if info.IsDir() {
1391→			return nil
1392→		}
1393→
1394→		// Get relative path within metadata dir
1395→		relPath, err := filepath.Rel(metadataDir, path)
1396→		if err != nil {
1397→			return fmt.Errorf("failed to get relative path for %s: %w", path, err)
1398→		}
1399→
1400→		// Prevent path traversal via symlinks pointing outside the metadata dir
1401→		if strings.HasPrefix(relPath, "..") {
1402→			return fmt.Errorf("path traversal detected: %s", relPath)
1403→		}
1404→
1405→		// Create blob from file with secrets redaction
1406→		blobHash, mode, err := createRedactedBlobFromFile(s.repo, path, relPath)
1407→		if err != nil {
1408→			return fmt.Errorf("failed to create blob for %s: %w", path, err)
1409→		}
1410→
1411→		// Store at checkpoint path (use forward slashes for git tree compatibility on Windows)
1412→		fullPath := basePath + filepath.ToSlash(relPath)
1413→		entries[fullPath] = object.TreeEntry{
1414→			Name: fullPath,
1415→			Mode: mode,
1416→			Hash: blobHash,
1417→		}
1418→
1419→		return nil
1420→	})
1421→	if err != nil {
1422→		return fmt.Errorf("failed to walk metadata directory: %w", err)
1423→	}
1424→	return nil
1425→}
1426→
1427→// createRedactedBlobFromFile reads a file, applies secrets redaction, and creates a git blob.
1428→// JSONL files get JSONL-aware redaction; all other files get plain string redaction.
1429→func createRedactedBlobFromFile(repo *git.Repository, filePath, treePath string) (plumbing.Hash, filemode.FileMode, error) {
1430→	info, err := os.Stat(filePath)
1431→	if err != nil {
1432→		return plumbing.ZeroHash, 0, fmt.Errorf("failed to stat file: %w", err)
1433→	}
1434→
1435→	mode := filemode.Regular
1436→	if info.Mode()&0o111 != 0 {
1437→		mode = filemode.Executable
1438→	}
1439→
1440→	content, err := os.ReadFile(filePath) //nolint:gosec // filePath comes from walking the metadata directory
1441→	if err != nil {
1442→		return plumbing.ZeroHash, 0, fmt.Errorf("failed to read file: %w", err)
1443→	}
1444→
1445→	// Skip redaction for binary files — they can't contain text secrets and
1446→	// running string replacement on them would corrupt the data.
1447→	isBin, binErr := binary.IsBinary(bytes.NewReader(content))
1448→	if binErr != nil || isBin {
1449→		hash, err := CreateBlobFromContent(repo, content)
1450→		if err != nil {
1451→			return plumbing.ZeroHash, 0, fmt.Errorf("failed to create blob: %w", err)
1452→		}
1453→		return hash, mode, nil
1454→	}
1455→
1456→	if strings.HasSuffix(treePath, ".jsonl") {
1457→		redacted, jsonlErr := redact.JSONLBytes(content)
1458→		if jsonlErr != nil {
1459→			redacted = redact.Bytes(content)
1460→		}
1461→		content = redacted
1462→	} else {
1463→		content = redact.Bytes(content)
1464→	}
1465→
1466→	hash, err := CreateBlobFromContent(repo, content)
1467→	if err != nil {
1468→		return plumbing.ZeroHash, 0, fmt.Errorf("failed to create blob: %w", err)
1469→	}
1470→	return hash, mode, nil
1471→}
1472→
1473→// GetGitAuthorFromRepo retrieves the git user.name and user.email,
1474→// checking both the repository-local config and the global ~/.gitconfig.
1475→func GetGitAuthorFromRepo(repo *git.Repository) (name, email string) {
1476→	// Get repository config (includes local settings)
1477→	cfg, err := repo.Config()
1478→	if err == nil {
1479→		name = cfg.User.Name
1480→		email = cfg.User.Email
1481→	}
1482→
1483→	// If not found in local config, try global config
1484→	if name == "" || email == "" {
1485→		globalCfg, err := config.LoadConfig(config.GlobalScope)
1486→		if err == nil {
1487→			if name == "" {
1488→				name = globalCfg.User.Name
1489→			}
1490→			if email == "" {
1491→				email = globalCfg.User.Email
1492→			}
1493→		}
1494→	}
1495→
1496→	// Provide sensible defaults if git user is not configured
1497→	if name == "" {
1498→		name = "Unknown"
1499→	}
1500→	if email == "" {
1501→		email = "unknown@local"
1502→	}
1503→
1504→	return name, email
1505→}
1506→
1507→// CreateCommit creates a git commit object with the given tree, parent, message, and author.
1508→// If parentHash is ZeroHash, the commit is created without a parent (orphan commit).
1509→func CreateCommit(repo *git.Repository, treeHash, parentHash plumbing.Hash, message, authorName, authorEmail string) (plumbing.Hash, error) {
1510→	now := time.Now()
1511→	sig := object.Signature{
1512→		Name:  authorName,
1513→		Email: authorEmail,
1514→		When:  now,
1515→	}
1516→
1517→	commit := &object.Commit{
1518→		TreeHash:  treeHash,
1519→		Author:    sig,
1520→		Committer: sig,
1521→		Message:   message,
1522→	}
1523→
1524→	if parentHash != plumbing.ZeroHash {
1525→		commit.ParentHashes = []plumbing.Hash{parentHash}
1526→	}
1527→
1528→	obj := repo.Storer.NewEncodedObject()
1529→	if err := commit.Encode(obj); err != nil {
1530→		return plumbing.ZeroHash, fmt.Errorf("failed to encode commit: %w", err)
1531→	}
1532→
1533→	hash, err := repo.Storer.SetEncodedObject(obj)
1534→	if err != nil {
1535→		return plumbing.ZeroHash, fmt.Errorf("failed to store commit: %w", err)
1536→	}
1537→
1538→	return hash, nil
1539→}
1540→
1541→// readTranscriptFromTree reads a transcript from a git tree, handling both chunked and non-chunked formats.
1542→// It checks for chunk files first (.001, .002, etc.), then falls back to the base file.
1543→// The agentType is used for reassembling chunks in the correct format.
1544→func readTranscriptFromTree(ctx context.Context, tree *FetchingTree, agentType types.AgentType) ([]byte, error) {
1545→	// Collect all transcript-related files
1546→	var chunkFiles []string
1547→	var hasBaseFile bool
1548→
1549→	for _, entry := range tree.RawEntries() {
1550→		if entry.Name == paths.TranscriptFileName || entry.Name == paths.TranscriptFileNameLegacy {
1551→			hasBaseFile = true
1552→		}
1553→		// Check for chunk files (full.jsonl.001, full.jsonl.002, etc.)
1554→		if strings.HasPrefix(entry.Name, paths.TranscriptFileName+".") {
1555→			idx := agent.ParseChunkIndex(entry.Name, paths.TranscriptFileName)
1556→			if idx > 0 {
1557→				chunkFiles = append(chunkFiles, entry.Name)
1558→			}
1559→		}
1560→	}
1561→
1562→	// If we have chunk files, read and reassemble them
1563→	if len(chunkFiles) > 0 {
1564→		// Sort chunk files by index
1565→		chunkFiles = agent.SortChunkFiles(chunkFiles, paths.TranscriptFileName)
1566→
1567→		// Check if base file should be included as chunk 0.
1568→		// NOTE: This assumes the chunking convention where the unsuffixed file
1569→		// (full.jsonl) is chunk 0, and numbered files (.001, .002) are chunks 1+.
1570→		if hasBaseFile {
1571→			chunkFiles = append([]string{paths.TranscriptFileName}, chunkFiles...)
1572→		}
1573→
1574→		var chunks [][]byte
1575→		for _, chunkFile := range chunkFiles {
1576→			file, err := tree.File(chunkFile)
1577→			if err != nil {
1578→				logging.Warn(ctx, "failed to read transcript chunk file from tree",
1579→					slog.String("chunk_file", chunkFile),
1580→					slog.String("error", err.Error()),
1581→				)
1582→				continue
1583→			}
1584→			content, err := file.Contents()
1585→			if err != nil {
1586→				logging.Warn(ctx, "failed to read transcript chunk contents",
1587→					slog.String("chunk_file", chunkFile),
1588→					slog.String("error", err.Error()),
1589→				)
1590→				continue
1591→			}
1592→			chunks = append(chunks, []byte(content))
1593→		}
1594→
1595→		if len(chunks) > 0 {
1596→			result, err := agent.ReassembleTranscript(chunks, agentType)
1597→			if err != nil {
1598→				return nil, fmt.Errorf("failed to reassemble transcript: %w", err)
1599→			}
1600→			return result, nil
1601→		}
1602→	}
1603→
1604→	// Fall back to reading base file (non-chunked or backwards compatibility)
1605→	if file, err := tree.File(paths.TranscriptFileName); err == nil {
1606→		if content, err := file.Contents(); err == nil {
1607→			return []byte(content), nil
1608→		}
1609→	}
1610→
1611→	// Try legacy filename
1612→	if file, err := tree.File(paths.TranscriptFileNameLegacy); err == nil {
1613→		if content, err := file.Contents(); err == nil {
1614→			return []byte(content), nil
1615→		}
1616→	}
1617→
1618→	return nil, nil
1619→}
1620→
1621→// Author contains author information for a checkpoint.
1622→type Author struct {
1623→	Name  string
1624→	Email string
1625→}
1626→
1627→// GetCheckpointAuthor retrieves the author of a checkpoint from the entire/checkpoints/v1 commit history.
1628→// Finds the commit whose subject matches "Checkpoint: <id>" and returns its author.
1629→// Returns empty Author if the checkpoint is not found or the sessions branch doesn't exist.
1630→func (s *GitStore) GetCheckpointAuthor(ctx context.Context, checkpointID id.CheckpointID) (Author, error) {
1631→	if err := ctx.Err(); err != nil {
1632→		return Author{}, err //nolint:wrapcheck // Propagating context cancellation
1633→	}
1634→
1635→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
1636→	ref, err := s.repo.Reference(refName, true)
1637→	if err != nil {
1638→		return Author{}, nil
1639→	}
1640→
1641→	// Search for the commit whose subject matches "Checkpoint: <id>"
1642→	targetSubject := "Checkpoint: " + checkpointID.String()
1643→
1644→	iter, err := s.repo.Log(&git.LogOptions{
1645→		From:  ref.Hash(),
1646→		Order: git.LogOrderCommitterTime,
1647→	})
1648→	if err != nil {
1649→		return Author{}, nil
1650→	}
1651→	defer iter.Close()
1652→
1653→	var author Author
1654→	err = iter.ForEach(func(c *object.Commit) error {
1655→		if err := ctx.Err(); err != nil {
1656→			return err //nolint:wrapcheck // Propagating context cancellation
1657→		}
1658→		subject := strings.SplitN(c.Message, "\n", 2)[0]
1659→		if subject == targetSubject {
1660→			author = Author{
1661→				Name:  c.Author.Name,
1662→				Email: c.Author.Email,
1663→			}
1664→			return errStopIteration
1665→		}
1666→		return nil
1667→	})
1668→
1669→	if err != nil && !errors.Is(err, errStopIteration) {
1670→		return Author{}, nil
1671→	}
1672→
1673→	return author, nil
1674→}
1675→

